from re import match

from taf.rfrl.procedures.resources.python.logger import log_env_state
from taf.rfrl.procedures.resources.python.sw_update.exceptions import InvalidSwVersion
from taf.rfrl.procedures.resources.python.sw_update.sw_version.sw_version import SwVersion


class SbtsSwVersion(SwVersion):
    """ Represents SBTS software version """

    def __init__(self, raw):
        super().__init__(raw)
        self._artifactory_dirs = {'9999': 'SBTS00', '9200': 'SBTS_FEINT', '9000': 'SBTS_PSINT', '9001': 'SBTS_PSINT2',
                                  '9990': 'SBTS00', '9501': 'NIDD_INT1', '9502': 'NIDD_INT2'}

    @property
    def package(self):
        """
        Returns SW version in package name format, i.e.
        'SBTS00_ENB_9999_210318_000011_release_BTSSM_downloadable_A54.zip'

        :rtype: str
        """
        if self._package is None:
            sbts_header, _, head, mid, tail = self.raw.split('_')
            if head in self._artifactory_dirs.keys():
                sbts_header = "SBTS00"
            elif head == "0000":
                self._artifactory_dirs[head] = sbts_header
            test = ''

            if self.raw.endswith('T1'):
                tail = tail.replace('T1', '')
                test = '_testpackage_T1'
            elif self.raw.endswith('T2'):
                tail = tail.replace('T2', '')
                test = '_testpackage_T2'

            tail = tail.zfill(6)

            self._package = (
                "{}_ENB_{}_{}_{}_release_BTSSM_downloadable{}_A54.zip".format(
                    sbts_header, head, mid, tail, test
                )
            )
        return self._package

    @property
    def url(self):
        """
        Returns SW version in URL format, i.e.
        'https://artifactory-espoo2.int.net.nokia.com/artifactory/mn-cosi-sran-central-public-local/
        build/SBTS00/SBTS00_ENB_9999_230724_000016/SBTS00_ENB_9999_230724_000016_release_BTSSM_downloadable_A54.zip'

        :rtype: str
        """
        if self._url is None:
            package = self.package
            head = package.split('_')[2]
            self._url = (
                "https://artifactory-espoo2.int.net.nokia.com/artifactory/"
                "mn-cosi-sran-central-public-local/build/{}/{}/{}".format(
                    self._artifactory_dirs[head], package.split("_release")[0], package
                )
            )
            log_env_state(f'{self.__class__.__name__} url: {self._url}')
        return self._url

    @property
    def packages_url(self):
        """
        Returns URL to all available packages for particular SW version, i.e.
        'https://artifactory-espoo2.int.net.nokia.com/artifactory/mn-cosi-sran-central-public-local/
        build/SBTS00/SBTS00_ENB_9999_230724_000016/'

        :rtype: str
        """
        if self._packages_url is None:
            package = self.package
            head = package.split('_')[2]
            self._packages_url = (
                "https://artifactory-espoo2.int.net.nokia.com/artifactory/"
                "mn-cosi-sran-central-public-local/build/{}/{}/".format(
                    self._artifactory_dirs[head], package.split("_release")[0]
                )
            )
        return self._packages_url

    @property
    def checksum(self):
        """
        Returns checksum of SW package.

        :rtype: str
        """
        return self._checksum

    def _validate_raw(self, raw):
        """
        Checks whether given raw SW version number is correct.

        :param raw: SW version in raw format, i.e.:
         'SBTS21B_ENB_9999_210318_000011' for regular software version,
         'SBTS21B_ENB_9999_210318_000011T1' in case of test package 1
         'SBTS21B_ENB_9999_210318_0000110' with additional, seventh number in the last element for knife package
        :type raw: str
        :raises InvalidSwVersion: when given raw number is invalid
        """
        valid_raw_pattern = r'^SBTS[0-9A-R]{0,4}_ENB_[0-9]{4}_[0-9]{6}_[0-9]{6}(T[1-2])?$'

        if not match(valid_raw_pattern, raw):
            raise InvalidSwVersion('Cannot create {} from invalid raw input: {}'.format(self.__class__.__name__, raw))
